/bin/bash -lc "python - <<'PY'
from pathlib import Path
p=Path('index.html')
s=p.read_text()
s=s.replace('<div class=\"top\">\\n<header', '<div style=\"background:var(--lavender)\">\\n<header',1)
s=s.replace('</header>\\n<main>','</header>\\n</div>\\n<main>\\n<div class=\"top\">',1)
s=s.replace('<span class=\"demo-options\"', '<span class=\"demo-options\"')
p.write_text(s)
from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__(); self.stack=[]; self.ids=set(); self.links=[]; self.errors=[]
    def handle_starttag(self,tag,attrs):
        attrs=dict(attrs)
        if 'id' in attrs:
            if attrs['id'] in self.ids: self.errors.append('Duplicate ID '+attrs['id'])
            self.ids.add(attrs['id'])
        if tag=='a' and attrs.get('href','').startswith('#') and attrs['href']"'!='"'#':self.links.append(attrs['href'][1:])
        if tag not in {'area','base','br','col','embed','hr','img','input','link','meta','param','source','track','wbr'}: self.stack.append(tag)
    def handle_endtag(self,tag):
        if not self.stack or self.stack[-1]"'!=tag:self.errors.append(f'"'Misnested closing tag: {tag}; expected {self.stack[-1] if self.stack else \"none\"}')
        elif self.stack:self.stack.pop()
v=Validator();v.feed(s)
assert not v.stack, v.stack
assert not v.errors, v.errors
assert all(link in v.ids for link in v.links)
print('HTML nesting, unique IDs, and navigation anchors OK')
